## Why This Is Asked

This question tests the baseline understanding of secure, auditable cross-account access and basic automation for SAP parameter changes in an enterprise context.

## Key Concepts

- Cross-account trust via STS AssumeRole with temporal bounds
- CloudTrail logging of STS AssumeRole events and SSM parameter modifications
- SSM Parameter Store as a secure configuration datastore for SAP
- Lambda-based session revocation for temporal access control
- CloudWatch alarms for monitoring access deviation and automation failures

## Code Example

```javascript
// Minimal CDK snippet to create the cross-account trust role
import { Stack, StackProps } from 'aws-cdk-lib';
import { Role, ServicePrincipal, Policy, PolicyStatement, Effect, AccountPrincipal } from 'aws-cdk-lib/aws-iam';
import { Construct } from 'constructs';
import { Duration } from 'aws-cdk-lib';

export class CrossAccountSapRoleStack extends Stack {
  constructor(scope: Construct, id: string, props?: StackProps) {
    super(scope, id, props);

    const sapAdminRole = new Role(this, 'SapAdminRole', {
      roleName: 'SAP-ParameterAdmin-CrossAccount',
      assumedBy: new ServicePrincipal('sts.amazonaws.com'),
      maxSessionDuration: Duration.hours(12),
    });

    // Trust policy allowing specific Audit account to assume this role
    sapAdminRole.assumeRolePolicy.addStatements(
      new PolicyStatement({
        effect: Effect.ALLOW,
        principals: [new AccountPrincipal('111122223333')], // Audit Account ID
        actions: ['sts:AssumeRole'],
      })
    );

    // Permission policy for SSM Parameter Store access
    const ssmPolicy = new Policy(this, 'SapParameterPolicy', {
      policyName: 'SAP-Parameter-Access-Policy',
      statements: [
        new PolicyStatement({
          effect: Effect.ALLOW,
          actions: [
            'ssm:GetParameter',
            'ssm:PutParameter',
            'ssm:DescribeParameters',
          ],
          resources: ['arn:aws:ssm:*:*:parameter/sap/config/*'],
        }),
      ],
    });

    sapAdminRole.attachInlinePolicy(ssmPolicy);
  }
}
```

## CloudWatch Alert Path for Session Revocation

```javascript
// Lambda function to revoke access after 12-hour expiry
import { CloudWatchEventsClient, PutEventsCommand } from '@aws-sdk/client-cloudwatch-events';

const REGION = 'us-east-1';

export const handler = async (event) => {
  try {
    const detail = event.detail || {};
    const roleSessionName = detail.roleSessionName || 'SAP-Admin-Session';

    console.log(`Revoking session: ${roleSessionName}`);

    const cwClient = new CloudWatchEventsClient({ region: REGION });
    await cwClient.send(new PutEventsCommand({
      Entries: [{
        Source: 'sap.access.revocation',
        DetailType: 'Session Revoked',
        Detail: JSON.stringify({ status: 'success', timestamp: new Date().toISOString() }),
      }],
    }));

    return { statusCode: 200, body: 'Session revoked successfully' };
  } catch (error) {
    console.error('Revocation failed:', error);

    const alarmClient = new CloudWatchEventsClient({ region: REGION });
    await alarmClient.send(new PutEventsCommand({
      Entries: [{
        Source: 'sap.access.revocation.failure',
        DetailType: 'Revocation Alarm',
        Detail: JSON.stringify({ error: error.message, timestamp: new Date().toISOString() }),
      }],
    }));

    return { statusCode: 500, body: 'Revocation failed' };
  }
};
```

